export const importProjectResponseProjectIdMin = 36;
export const importProjectResponseProjectIdMax = 36;

export const importProjectResponseProjectIdRegExp = new RegExp(
  "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
);
export const importProjectResponseTaskCountMin = 0;
export const importProjectResponseTaskCountMax = 10000;

export const importProjectResponseRelationCountMin = 0;
export const importProjectResponseRelationCountMax = 50000;

export const importProjectResponseSessionCountMin = 0;
export const importProjectResponseSessionCountMax = 50000;

export const importProjectResponseKnowledgeCountMin = 0;
export const importProjectResponseKnowledgeCountMax = 50000;

export const ImportProjectResponse = zod
  .object({
    project_id: zod
      .uuid()
      .min(importProjectResponseProjectIdMin)
      .max(importProjectResponseProjectIdMax)
      .regex(importProjectResponseProjectIdRegExp)
      .describe("Identifier of the newly created project."),
    task_count: zod
      .int()
      .min(importProjectResponseTaskCountMin)
      .max(importProjectResponseTaskCountMax)
      .describe("Number of tasks imported."),
    relation_count: zod
      .int()
      .min(importProjectResponseRelationCountMin)
      .max(importProjectResponseRelationCountMax)
      .describe("Number of relations imported."),
    session_count: zod
      .int()
      .min(importProjectResponseSessionCountMin)
      .max(importProjectResponseSessionCountMax)
      .describe("Number of sessions imported."),
    knowledge_count: zod
      .int()
      .min(importProjectResponseKnowledgeCountMin)
      .max(importProjectResponseKnowledgeCountMax)
      .describe("Number of knowledge items imported."),
  })
  .describe("Result of a successful project import.");
